function normalize(value: unknown): unknown {
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'number' && !Number.isFinite(value)) throw new Error('non-finite numbers are not canonicalizable');
    return value;
  }
  if (Array.isArray(value)) return value.map(normalize);
  const out: Record<string,unknown> = {};
  for (const key of Object.keys(value as Record<string,unknown>).sort()) {
    const v=(value as Record<string,unknown>)[key];
    if (v !== undefined) out[key]=normalize(v);
  }
  return out;
}
export function canonicalize(value: unknown): string { return JSON.stringify(normalize(value)); }
export function hashCanonical(value: unknown): string { return 'sha256:'+createHash('sha256').update(canonicalize(value)).digest('hex'); }

