function evidence(id:string, cls:string, type:string, content:unknown, parents:string[]=[], privacy='INTERNAL'):GoldenEvidence {
  const payload={evidence_id:id,evidence_class:cls,evidence_type:type,content,parent_evidence_ids:parents};
  return {...payload,content_hash:hashCanonical(payload),created_at:'2026-10-03T22:00:00.000Z',privacy_class:privacy};
}
function eventBase(i:number,type:string,actor_id:string,actor_type:string, evidence_refs:string[]=[], source_refs:string[]=[], policy_refs:string[]=[POLICY], decision:string|null=null, reason_code:string|null=null):GoldenEvent {
  const payload:any={
    event_id:`evt_CLP001_${String(i).padStart(3,'0')}`,event_type:type,occurred_at:new Date(T0+i*60000).toISOString(),actor_id,actor_type,
    aggregate_id:CASE,aggregate_version:i,causation_event_id:i===1?null:`evt_CLP001_${String(i-1).padStart(3,'0')}`,correlation_id:CORR,
    input_refs:[],output_refs:[],source_refs,policy_refs,evidence_refs,decision,reason_code
  };
  return {...payload,event_hash:hashCanonical(payload)};
}
function chainEvents(events:GoldenEvent[]):ChainRecord[] {
  let previous:string|null=null;
  return events.map((e,idx)=>{
    const record={ordinal:idx+1,event_id:e.event_id,event_hash:e.event_hash,previous_chain_hash:previous};
    const chain_hash=hashCanonical({...record,correlation_id:e.correlation_id});
    previous=chain_hash;
    return {...record,chain_hash};
  });
}

